  flex-wrap: wrap;
  gap: 12px;
}

.brand {
  font-size: 1.35rem;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand .logo {
  width: 34px;
  height: 34px;
