  background: rgba(34, 197, 94, 0.12);
  border-color: var(--success);
  color: #86efac;
}

/* ---------- diversos ---------- */
.empty {
  text-align: center;
  color: var(--muted);
  padding: 40px 16px;
}

.section-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 24px 0 14px;
  flex-wrap: wrap;
  gap: 10px;
}

.section-title h2 {
  font-size: 1.15rem;
}

.actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.hint {
  font-size: 0.82rem;
  color: var(--muted);
}

.muted {
  color: var(--muted);
