function eventCard(e) {
  const full = e.status === "active" && e.spots <= 0;
  return `
    <div class="card event-card">
      <div class="date">
        <span>&#128197; ${fmtDate(e.date)}</span>
        <span>&#128336; ${fmtTime(e.time)}</span>
      </div>
      <h3>${escapeHtml(e.title)}</h3>
